INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Ledger IPO before 2027?', 'This market will resolve to "Yes" if the listed company completes an Initial Public Offering (IPO) by December 31, 2026, 11:59 PM ET, as confirmed by official company announcements or credible news sources. The IPO refers to the first sale of stock by the listed company to the public on any recognized stock exchange.

If the listed company merges with another entity, is acquired, or ceases to exist before the market resolves, the market will also resolve to "No".

This market will resolve early if the listed company completes an IPO by December 31, 2026, 11:59 PM ET.

The resolution source for this market is a consensus of credible reporting.', 'tech', 'active', 26934.33, 229583.11, 27434.33, 230083.11);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Clarity Act (H.R.3633) signed into law in 2026?', 'This market will resolve to "Yes" if the Digital Asset Market Clarity Act of 2025 (H.R.3633) is passed by both chambers of the U.S. Congress and signed into law by December 31, 2026, 11:59 PM ET. Otherwise, this market will resolve to "No".

The primary resolution source is Congress.gov’s legislation tracker (https://www.congress.gov/bill/119th-congress/house-bill/3633) and other official information from the government of the United States, however other credible reporting may be used.', 'crypto', 'active', 639827.4, 2818699.07, 640327.4, 2819199.07);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will the upper bound of the target federal funds rate be ≥ 4.5% at the end of 2026?', 'The FED rate is defined in this market by the upper bound of the target federal funds range. The decisions on the target federal fund range are made by the Federal Open Market Committee (FOMC) meetings.

This market will resolve according to the upper bound of the Federal Reserve’s target federal funds range after the December 2026 Federal Open Market Committee (FOMC) meeting, currently scheduled for December 8-9, 2026.

This market may resolve immediately after the statement for the FOMC’s December meeting, with relevant information about the FOMC’s decision on the target federal funds range, has been issued. If no FOMC decision on the target federal funds range for their December meeting has been issued by December 31, 2026, 11:59 PM ET, this market will resolve according to the upper bound of the target federal funds range at that time.

The upper bound of the target federal funds range will be rounded to the nearest 25 basis points for resolution of this market. If the upper bound of the target federal funds range falls exactly between two listed options, it will be rounded away from zero (e.g. if the upper bound is 2.875, with listed options of 3.0 & 2.75, this market will resolve to 3.0).

The primary resolution source for this market will be official information from the Federal Reserve (https://www.federalreserve.gov/monetarypolicy/openmarket.htm).', 'politics', 'active', 81867.73, 1122069.47, 82367.73, 1122569.47);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Opensea FDV above $500M one day after launch?', 'This market will resolve to "Yes" if the Fully Diluted Valuation of Opensea''s token is greater than the value specified in the title 1 day after launch. Otherwise, the market will resolve to "No."

The token must be actively, publicly transferable and tradable to be considered a launch.

"1 day after launch" is defined as 4:00 PM ET on the calendar day following launch. The resolution source for this market is the most liquid price source available. If Opensea doesn''t launch a token by December 31, 2026, 11:59 PM ET, this market will resolve to "No".', 'crypto', 'active', 133711.81, 994657.92, 134211.81, 995157.92);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will Katie Boulter win the 2026 Women’s US Open?', 'The 2026 U.S. Open tennis tournament is scheduled for August 23 - September 13, 2026.

This market will resolve to the player that wins the 2026 U.S. Open Women’s Singles Tournament.

If at any point it becomes impossible for a listed player to win the 2026 U.S. Open Women’s Singles Tournament per the rules of the tournament, the corresponding market will resolve to “No”.

If the 2026 U.S. Open Women’s Singles Tournament is cancelled, postponed after October 31, 2026, or there is otherwise no winner declared within that timeframe, this market will resolve to “Other”.

The primary resolution source will be official information from the U.S. Open (https://www.usopen.org/index.html); however, a consensus of credible reporting may also be used.', 'sports', 'active', 8327.64, 824436.65, 8827.64, 824936.65);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Mojtaba Khamenei seen in public by August 31?', 'This market will resolve to "Yes" if Supreme Leader of Iran, Mojtaba Khamenei, is photographed or videotaped between market creation and the listed date (ET). Otherwise, this market will resolve to "No".

For this market to resolve to "Yes," the images or video must be taken and released within this market''s timeframe. The images or video must be authentic. Archival material, previously recorded footage, reused images, digitally altered content, AI-generated media, staged reproductions, or any posthumous releases will not qualify.

Digital appearances, including live broadcasts, will count for this market.

The resolution source for this market will be the image/video of Mojtaba Khamenei, and a consensus of credible reporting as to whether it is real.', 'politics', 'active', 14529.47, 184504.41, 15029.47, 185004.41);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will Shakhtar Donetsk win the 2026-27 UEFA Champions League Championship?', 'This market will resolve according to the team that wins the 2026-27 UEFA Champions League Championship.

If at any point it becomes impossible for a listed team to win the 2026-27 UEFA Champions League Championship per the rules of UEFA Champions League (e.g., they are eliminated in the playoffs), the corresponding market will resolve to "No".

If the 2026-27 UEFA Champions League season is cancelled, postponed after June 19, 2027, 11:59 PM ET or there is otherwise no winner declared within that timeframe, this market will resolve to "Other".

The primary resolution source will be official information from UEFA Champions League; however, a consensus of credible reporting may also be used.', 'sports', 'active', 20874.01, 2066526.7, 21374.01, 2067026.7);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will María Corina Machado enter Venezuela by August 31?', 'If María Corina Machado visits Venezuela between market creation and August 31, 2026, 11:59 PM ET, this market will resolve to "Yes". Otherwise, this market will resolve to "No".

For the purpose of this market, a "visit" is defined as María Corina Machado physically entering the terrestrial territory of Venezuela. Whether or not María Corina Machado enters Venezuelan airspace or maritime territory during the timeframe of this market will have no bearing on a positive resolution.

The primary resolution source for this market will be a consensus of credible reporting.', 'politics', 'active', 270.15, 3885.95, 770.15, 4385.95);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Will Maxx Crosby play for New York Jets next?', 'This market will resolve to the next team Maxx Crosby officially joins by August 31, 2026, 11:59 PM ET.

If Maxx Crosby does not officially join a new team by August 31, 2026, 11:59 PM ET, this market will resolve to “Las Vegas Raiders”.

If Maxx Crosby joins a team that is not listed, this market will resolve to “Other”.

If Maxx Crosby is released and is not signed by another team, retires, or is not under contract with any professional team by August 31, 2026, 11:59 PM ET, this market will resolve to “Other”.

Transfers or assignments between a team’s senior team and reserve or affiliate teams will not be considered for this market.

An official signing announcement prior to the market’s close date will immediately resolve this market to the corresponding option.

The primary resolution sources for this market will be official announcements from the Las Vegas Raiders and/or the acquiring team. A consensus of credible media reporting may also be used to resolve the market.', 'sports', 'active', 6006.98, 594690.8, 6506.98, 595190.8);
INSERT INTO public.events (title, description, category, status, total_yes_pool, total_no_pool, cpmm_ry, cpmm_rn) VALUES ('Game 2: Any Player Quadra Kill?', 'This market is about whether any player achieves a Quadra Kill during Game 2. In League of Legends, a Quadra Kill occurs when a single player kills 4 enemy champions in rapid succession.

This market will resolve to "Yes" if any player on either team achieves a Quadra Kill during Game 2. This market will resolve to "No" if no player achieves a Quadra Kill. A Penta Kill (5 kills in rapid succession) also counts as a Quadra Kill having occurred for the purposes of this market.

If the match is canceled (not played at all) or is delayed beyond 7 days from the scheduled date, this market will resolve to 50-50.

If Game 2 is never played due to forfeit, disqualification, or walkover, this market will resolve to 50-50.

If Game 2 is not played because the series result has already been determined (e.g., a team clinches the series before Game 2 is needed), this market will resolve to 50-50.

If Game 2 begins but is not completed and ends via surrender, this market will resolve based on whether a Quadra Kill occurred prior to stoppage. If no Quadra Kill occurred, this market will resolve to "No".

If Game 2 is remade, resolution will be based on the remade game only.

The resolution source for this market will be official information from https://gol.gg/esports/home. However, if https://gol.gg/esports/home has not published final results within 2 hours after the event''s conclusion, a consensus of credible reporting may be used instead including video evidence.', 'sports', 'active', 1575304.04, 1575304.04, 1575804.04, 1575804.04);